import { Router } from 'express';
import { billingRoutes } from './billing.routes';
import { healthRoutes } from './health.routes';
import { internalRoutes } from './internal.routes';
import { loyaltyRoutes } from './loyalty.routes';
import { membershipRoutes } from './membership.routes';
import { packageRoutes } from './package.routes';
import { serviceRoutes } from './service.routes';
import { walletRoutes } from './wallet.routes';
const router = Router();
router.use('/', healthRoutes);
router.use('/internal/v1', internalRoutes);
router.use('/api/v1/services', serviceRoutes);
router.use('/api/v1/packages', packageRoutes);
router.use('/api/v1/memberships', membershipRoutes);
router.use('/api/v1/billing', billingRoutes);
router.use('/api/v1/customers/wallet', walletRoutes);
router.use('/api/v1/customers/loyalty', loyaltyRoutes);
export const apiRoutes = router;
